from trading.utils.indicators import atr

def _classify_one(symbol: str) -> dict:
    daily = _fetch_daily(symbol)
    if len(daily) < 25: return {... 'classification': 'no_data', 'pivot_high': 0.0, 'distance_pct': 0.0, 'distance_atr': 0.0}
    pivot_high = max(highs[-60:])
    distance_pct = (close - pivot_high) / pivot_high * 100
    a = atr(highs, lows, closes, 14)
    distance_atr = (close - pivot_high) / a if a > 0 else 0.0
    # classification: still_in_base if close < pivot_high and base_depth >= 5
    # fresh if 0 <= distance_pct <= 3 OR 0 <= distance_atr <= 1
    # extended otherwise (distance_pct > 8 or distance_atr > 3)
    return {..., 'pivot_high': round(pivot_high,2), 'distance_pct': round(distance_pct,2), 'distance_atr': round(distance_atr,2), 'classification': classification}

def build_breakout_classifier(symbols=None):
    syms = symbols or _watchlist()
    rows = [_classify_one(s) for s in syms[:30]]
    return {'rows': rows, 'count': len(rows)}

